164	fn complete_arg(
165	    arg: &clap_lex::ParsedArg<'_>,
166	    cmd: &clap::Command,
167	    current_dir: Option<&std::path::Path>,
168	    pos_index: usize,
169	    is_escaped: bool,
170	    state: ParseState<'_>,
171	    disabled: &HashSet<Id>,
172	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
173	    debug!(
174	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
175	        arg,
176	        cmd.get_name(),
177	        current_dir,
178	        pos_index,
179	        state
180	    );
181	    let mut completions = Vec::<CompletionCandidate>::new();
182	
183	    match state {
184	        ParseState::ValueDone => {
185	            // A closed `--name=value` word (or a short cluster carrying an
186	            // inline value, e.g. `-ovalue` / `-o=value`) is the option's value
187	            // position: only the option's own values are completed, exactly as
188	            // if the value had been written as a separate word.  The content
189	            // after `=` never takes part in subcommand, positional or
190	            // option-name completion, and the word itself is not yet part of
191	            // the conflict set.
192	            if !is_escaped {
193	                if let Some(values) = complete_inline_option_value(arg, cmd, current_dir, disabled)
194	                {
195	                    completions.extend(values);
196	                    return finalize_completions(completions);
197	                }
198	            }
199	
200	            // After `--`, only positional arguments are completed.
201	            if !is_escaped {
202	                if let Ok(value) = arg.to_value() {
203	                    completions.extend(complete_subcommand(value, cmd));
204	                }
205	            }
206	
207	            if let Some(positional) = cmd
208	                .get_positionals()
209	                .find(|p| p.get_index() == Some(pos_index))
210	            {
211	                if !disabled.contains(positional.get_id()) {
212	                    completions.extend(complete_arg_value(
213	                        arg.to_value(),
214	                        positional,
215	                        current_dir,
216	                        0,
217	                    ));
218	                }
219	            }
220	            if !is_escaped {
221	                completions.extend(complete_option(arg, cmd, current_dir, disabled));
222	            }
223	        }
224	        ParseState::Pos((_, num_arg)) => {
225	            if let Some(positional) = cmd
226	                .get_positionals()
227	                .find(|p| p.get_index() == Some(pos_index))
228	            {
229	                if !disabled.contains(positional.get_id()) {
230	                    completions.extend(complete_arg_value(
231	                        arg.to_value(),
232	                        positional,
233	                        current_dir,
234	                        num_arg.saturating_sub(1),
235	                    ));
236	                }
237	                if !is_escaped
238	                    && positional
239	                        .get_num_args()
240	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
241	                {
242	                    completions.extend(complete_option(arg, cmd, current_dir, disabled));
243	                }
244	            }
245	        }
246	        ParseState::Opt((opt, count)) => {
247	            if !disabled.contains(opt.get_id()) {
248	                completions.extend(complete_arg_value(
249	                    arg.to_value(),
250	                    opt,
251	                    current_dir,
252	                    count.saturating_sub(1),
253	                ));
254	            }
255	            let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
256	            if count > min {
257	                // Also complete this raw_arg as a positional argument, flags, options and subcommand.
258	                completions.extend(complete_arg(
259	                    arg,
260	                    cmd,
261	                    current_dir,
262	                    pos_index,
263	                    is_escaped,
264	                    ParseState::ValueDone,
265	                    disabled,
266	                )?);
267	            }
268	        }
269	    }
270	
271	    finalize_completions(completions)
272	}
