308	/// Complete the inline value carried by the cursor's option word.
309	///
310	/// This covers `--name=value` as well as short clusters with an attached
311	/// value, e.g. `-ovalue` and `-o=value` (including leading flags, `-abovalue`).
312	/// It returns the option's value candidates, re-prefixed with the exact
313	/// option spelling, when the cursor is inside such a value.  The whole word is
314	/// consumed by its option: nothing after `=` or past the taking flag takes
315	/// part in option-name, subcommand or positional completion, and the word is
316	/// not yet part of the conflict set.
317	///
318	/// A bare `--name`/`-o` whose value is still a separate word completes
319	/// normally, as does an unknown long name, a recognized option that takes no
320	/// value and anything else that cannot be recognized: `None` preserves the
321	/// existing failure semantics rather than guessing a split.
322	fn complete_inline_option_value(
323	    arg: &clap_lex::ParsedArg<'_>,
324	    cmd: &clap::Command,
325	    current_dir: Option<&std::path::Path>,
326	    disabled: &HashSet<Id>,
327	) -> Option<Vec<CompletionCandidate>> {
328	    if let Some((flag, value)) = arg.to_long() {
329	        let flag = flag.ok()?;
330	        // A bare `--name` has no attached value and is completed as an option name.
331	        let value = value?;
332	        let opt = cmd.get_arguments().find(|a| {
333	            a.get_long_and_visible_aliases()
334	                .is_some_and(|longs| longs.into_iter().any(|long| long == flag))
335	        })?;
336	        if !opt.get_num_args().expect("built").takes_values() {
337	            return None;
338	        }
339	        if disabled.contains(opt.get_id()) {
340	            return Some(Vec::new());
341	        }
342	        return Some(
343	            complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
344	                .into_iter()
345	                .map(|comp| comp.add_prefix(format!("--{flag}=")))
346	                .collect(),
347	        );
348	    }
349	
350	    let short = arg.to_short()?;
351	    if short.is_negative_number() {
352	        return None;
353	    }
354	    let (leading_flags, opt, mut value_flags, _) = parse_shortflags(cmd, short);
355	    let opt = opt?;
356	
357	    // Detect an attached value: once the cluster reaches its value-taking
358	    // flag, everything left is the value, optionally introduced by `=`.  With
359	    // no remainder and no `=` (`-o`), the word is left to the regular option
360	    // completion, which already offers inline values.
361	    let mut peek = value_flags.clone();
362	    let has_equal = matches!(peek.next_flag(), Some(Ok('=')));
363	    if !has_equal && value_flags.is_empty() {
364	        return None;
365	    }
366	    if has_equal {
367	        // Consume the `=` so the remainder is the bare value (possibly empty
368	        // for `-o=`), matching the space-separated empty-value position.
369	        value_flags.next_flag();
370	    }
371	    if disabled.contains(opt.get_id()) {
372	        return Some(Vec::new());
373	    }
374	    let value = value_flags.next_value_os().unwrap_or(OsStr::new(""));
375	    let sep = if has_equal { "=" } else { "" };
376	    Some(
377	        complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
378	            .into_iter()
379	            .map(|comp| comp.add_prefix(format!("-{leading_flags}{sep}")))
380	            .collect(),
381	    )
382	}
