493	fn complete_arg_value(
494	    value: Result<&str, &OsStr>,
495	    arg: &clap::Arg,
496	    current_dir: Option<&std::path::Path>,
497	    arg_index: usize,
498	) -> Vec<CompletionCandidate> {
499	    let mut values = Vec::new();
500	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
501	
502	    let (prefix, value) =
503	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
504	
505	    let value_os = match value {
506	        Ok(value) => OsStr::new(value),
507	        Err(value_os) => value_os,
508	    };
509	
510	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
511	        values.extend(completer.complete_at(arg_index, value_os));
512	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
513	        values.extend(complete_value_candidates(
514	            value_os,
515	            completer.value_candidates(),
516	        ));
517	    } else if let Some(possible_values) = possible_values(arg) {
518	        if let Ok(value) = value {
519	            values.extend(complete_candidates_str(
520	                value,
521	                possible_value_candidates(possible_values),
522	            ));
523	        }
524	    } else {
525	        match arg.get_value_hint() {
526	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
527	                // Should not complete
528	            }
529	            clap::ValueHint::AnyPath => {
530	                values.extend(complete_path(value_os, current_dir, &|_| true));
531	            }
532	            clap::ValueHint::FilePath => {
533	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
534	            }
535	            clap::ValueHint::DirPath => {
536	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
537	            }
538	            clap::ValueHint::ExecutablePath => {
539	                use is_executable::IsExecutable;
540	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
541	            }
542	            clap::ValueHint::CommandName
543	            | clap::ValueHint::CommandString
544	            | clap::ValueHint::CommandWithArguments
545	            | clap::ValueHint::Username
546	            | clap::ValueHint::Hostname
547	            | clap::ValueHint::Url
548	            | clap::ValueHint::EmailAddress => {
549	                // No completion implementation
550	            }
551	            _ => {
552	                // Safe-ish fallback
553	                values.extend(complete_path(value_os, current_dir, &|_| true));
554	            }
555	        }
556	
557	        values.sort();
558	    }
559	
560	    if let Some(prefix) = prefix {
561	        values = values
562	            .into_iter()
563	            .map(|comp| comp.add_prefix(prefix))
564	            .collect();
565	    }
566	    values = values
567	        .into_iter()
568	        .map(|comp| {
569	            if comp.get_tag().is_some() {
570	                comp
571	            } else {
572	                comp.tag(Some(arg.to_string().into()))
573	            }
574	        })
575	        .collect();
576	
577	    debug!("complete_arg_value: values={values:?}");
578	    values
579	}
580	
581	fn rsplit_delimiter<'s, 'o>(
582	    value: Result<&'s str, &'o OsStr>,
583	    delimiter: Option<char>,
584	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
585	    let delimiter = delimiter?;
586	    let value = value.ok()?;
587	    let pos = value.rfind(delimiter)?;
588	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
589	    Some((Some(prefix), Ok(value)))
590	}
591	
592	fn complete_value_candidates(
593	    value: &OsStr,
594	    completer: &dyn ValueCandidates,
595	) -> Vec<CompletionCandidate> {
596	    debug!("complete_value_candidates: value={value:?}");
597	
598	    let mut values = completer.candidates();
599	    values.retain(|comp| comp.get_value().starts_with(&value.to_string_lossy()));
600	    values
601	}
