774	/// Parse the short flags and find the first `takes_values` option.
775	///
776	/// The returned bool is `true` only when every scanned cluster member was a
777	/// recognized option. Anything after the first value-taking option is the
778	/// option's value and therefore not scanned; invalid UTF-8 and unknown short
779	/// characters make the result `false`.
780	fn parse_shortflags<'c, 's>(
781	    cmd: &'c clap::Command,
782	    mut short: clap_lex::ShortFlags<'s>,
783	) -> (
784	    String,
785	    Option<&'c clap::Arg>,
786	    clap_lex::ShortFlags<'s>,
787	    bool,
788	) {
789	    let takes_value_opt;
790	    let mut leading_flags = String::new();
791	    let mut cluster_valid = true;
792	    // Find the first takes_values option.
793	    loop {
794	        match short.next_flag() {
795	            Some(Ok(opt)) => {
796	                leading_flags.push(opt);
797	                let found = cmd.get_arguments().find(|a| {
798	                    let shorts = a.get_short_and_visible_aliases();
799	                    let is_find = shorts.map(|v| {
800	                        let mut iter = v.into_iter();
801	                        let c = iter.find(|c| *c == opt);
802	                        c.is_some()
803	                    });
804	                    is_find.unwrap_or(false)
805	                });
806	                if let Some(opt) = found {
807	                    if opt.get_num_args().expect("built").takes_values() {
808	                        takes_value_opt = Some(opt);
809	                        break;
810	                    }
811	                } else {
812	                    cluster_valid = false;
813	                }
814	            }
815	            Some(Err(_)) => {
816	                cluster_valid = false;
817	                takes_value_opt = None;
818	                break;
819	            }
820	            None => {
821	                takes_value_opt = None;
822	                break;
823	            }
824	        }
825	    }
826	
827	    (leading_flags, takes_value_opt, short, cluster_valid)
828	}
829	
830	/// Parse the positional arguments. Return the new state and the new positional index.
831	fn parse_positional<'a>(
832	    cmd: &clap::Command,
833	    pos_index: usize,
834	    is_escaped: bool,
835	    state: ParseState<'a>,
836	) -> (ParseState<'a>, usize) {
837	    let pos_arg = cmd
838	        .get_positionals()
839	        .find(|p| p.get_index() == Some(pos_index));
840	    let num_args = pos_arg
841	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
842	        .unwrap_or(1);
843	
844	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
845	        if num_args > 1 {
846	            (ParseState::Pos((pos_index, 1)), pos_index)
847	        } else {
848	            if is_escaped {
849	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
850	            } else {
851	                (ParseState::ValueDone, pos_index + 1)
852	            }
853	        }
854	    };
855	    match state {
856	        ParseState::ValueDone => {
857	            update_state_with_new_positional(pos_index)
858	        },
859	        ParseState::Pos((prev_pos_index, num_arg)) => {
860	            if prev_pos_index == pos_index {
861	                if num_arg + 1 < num_args {
862	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
863	                } else {
864	                    if is_escaped {
865	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
866	                    } else {
867	                        (ParseState::ValueDone, pos_index + 1)
868	                    }
869	                }
870	            } else {
871	                update_state_with_new_positional(pos_index)
872	            }
873	        }
874	        ParseState::Opt(..) => unreachable!(
875	            "This branch won't be hit,
876	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
877	        ),
878	    }
879	}
880	
881	/// Parse optional flag argument. Return new state
882	fn parse_opt_value(opt: &clap::Arg, count: usize) -> ParseState<'_> {
883	    let range = opt.get_num_args().expect("built");
884	    let max = range.max_values();
885	    if count < max {
886	        ParseState::Opt((opt, count + 1))
887	    } else {
888	        ParseState::ValueDone
889	    }
890	}
891	
892	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
893	    cmd.get_positionals()
894	        .find(|a| a.get_index() == Some(pos_index))
895	        .map(|p| p.is_allow_hyphen_values_set())
896	        .unwrap_or(false)
897	}
898	
899	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
900	    let val = arg.to_value_os();
901	    if val.starts_with("-") {
902	        if let ParseState::Opt((opt, _)) = state {
903	            return opt.is_allow_hyphen_values_set();
904	        }
905	    }
906	
907	    false
908	}
909	
910	/// Arguments that must not be offered because they conflict with an explicitly
911	/// present option. The present options themselves are never disabled.
912	fn gather_disabled_args(cmd: &clap::Command, explicit: &HashSet<Id>) -> HashSet<Id> {
913	    let mut disabled = HashSet::new();
914	    if explicit.is_empty() {
915	        return disabled;
916	    }
917	    for arg in cmd.get_arguments() {
918	        if explicit.contains(arg.get_id()) {
919	            // A present option hides everything it conflicts with ...
920	            for id in arg_direct_conflicts(cmd, arg) {
921	                if !explicit.contains(&id) {
922	                    disabled.insert(id);
923	                }
924	            }
925	        } else {
926	            // ... and is hidden when either side declares the conflict.
927	            if arg_direct_conflicts(cmd, arg)
928	                .iter()
929	                .any(|id| explicit.contains(id))
930	            {
931	                disabled.insert(arg.get_id().clone());
932	            }
933	        }
934	    }
935	    disabled
936	}
937	
938	/// Conflict partners of `arg`, following the same rules as clap's parser:
939	/// - the argument's own `conflicts_with` / `conflicts_with_all`
940	/// - `conflicts_with` / `conflicts_with_all` of every group the argument belongs to
941	/// - the other members of non-`multiple` groups
942	///
943	/// Group ids are expanded to their argument members.
944	/// `overrides_with` relationships are intentionally not considered.
945	fn arg_direct_conflicts(cmd: &clap::Command, arg: &clap::Arg) -> HashSet<Id> {
946	    let mut conflicts = arg
947	        .get_conflicts_with()
948	        .map(ToOwned::to_owned)
949	        .collect::<HashSet<_>>();
950	    for group in cmd.get_groups() {
951	        let members = unroll_group(cmd, group.get_id());
952	        if !members.iter().any(|m| m == arg.get_id()) {
953	            continue;
954	        }
955	        conflicts.extend(group.get_conflicts_with().map(ToOwned::to_owned));
956	        if !group.is_multiple_set() {
957	            conflicts.extend(members.into_iter().filter(|m| m != arg.get_id()));
958	        }
959	    }
960	    conflicts
961	        .iter()
962	        .flat_map(|id| unroll_group(cmd, id))
963	        .collect()
964	}
965	
966	/// Resolve an argument or group id to its argument members.
967	/// Unknown ids resolve to themselves.
968	fn unroll_group(cmd: &clap::Command, id: &Id) -> Vec<Id> {
969	    let mut pending = vec![id.clone()];
970	    let mut args = Vec::new();
971	    while let Some(id) = pending.pop() {
972	        if cmd.get_arguments().any(|a| a.get_id() == &id) {
973	            if !args.contains(&id) {
974	                args.push(id);
975	            }
976	        } else if let Some(group) = cmd.get_groups().find(|g| g.get_id() == &id) {
977	            pending.extend(group.get_args().map(ToOwned::to_owned));
978	        } else if !args.contains(&id) {
979	            args.push(id);
980	        }
981	    }
982	    args
983	}
