    opt: &'a clap::Arg,
    mut consumed: usize,
    mut used: Vec<OsString>,
    value: &str,
    delimiter: char,
    closes: bool,
) -> Option<ParseState<'a>> {
    let max = opt.get_num_args().expect("built").max_values();
    let trailing = value.ends_with(delimiter);
    let segments: Vec<&str> = value.split(delimiter).collect();
    // For a trailing delimiter, the final empty segment is the pending one.
    let completed = if trailing { &segments[..segments.len() - 1] } else { &segments[..] };
    // Validate segments
    for seg in completed {
        if seg.is_empty() { return None; }  // empty value segment
        if let Some(possible) = possible_values(opt) {
            if !possible.any(|p| p.get_name() == *seg) { return None; }  // unknown value
        }
