    consumed += completed.len();
    if consumed > max { return None; }  // too many values
    if trailing && consumed == max { return None; }  // illegal delimiter position: no room for the promised value
    used.extend(completed.iter().map(OsString::from));
    if trailing {
        Some(ParseState::Opt((opt, consumed + 1, used)))
    } else if closes || consumed == max {
        None  // ValueDone
    } else {
        Some(ParseState::Opt((opt, consumed + 1, used)))
    }
}
