```rust
/// A delimiter-carrying cursor value is invalid when a completed segment is
/// empty or unknown, or when the segment under the cursor would exceed the
/// option's value limit.  Invalid words produce no candidates; they fail with
/// the same `no completion generated` error as any other dead end instead of
/// fabricating candidates for values the parser would reject.
fn validate_cursor_delimited(
    opt: &clap::Arg,
    value: Result<&str, &OsStr>,
    consumed: usize,
    delimiter: char,
) -> Result<(), std::io::Error> {
    let Ok(value) = value else {
        return Ok(());
    };
    let max = opt.get_num_args().expect("built").max_values();
    let segments: Vec<&str> = value.split(delimiter).collect();
    // The last segment is the one under the cursor; everything before it is
    // completed and must be valid on its own.
    let completed = &segments[..segments.len() - 1];
    for segment in completed {
        if segment.is_empty() || is_unknown_value(opt, segment) {
            return Err(no_completion());
        }
    }
    if consumed + completed.len() >= max {
        return Err(no_completion());
    }
    Ok(())
}
```

