fn parse_opt_value(opt: &clap::Arg, count: usize, used: Vec<OsString>) -> ParseState<'_> {
    let range = opt.get_num_args().expect("built");
    let max = range.max_values();
    if count < max {
        ParseState::Opt((opt, count + 1, used))
    } else {
        ParseState::ValueDone
    }
}
